export const clamp=(v,a,b)=>Math.min(b,Math.max(a,Number(v)||0));
export function resistance(r){r/=100;return r<0?1-r/2:r<.75?1-r:1/(4*r+1)}
export function stats(c){let s={atkPct:0,atkFlat:0,hpPct:0,hpFlat:0,defPct:0,defFlat:0,em:0,cr:0,cd:0,er:0,dmg:0};for(const a of c.artifacts)for(const x of [a.main,...a.subs])s[x.stat]=(s[x.stat]||0)+Number(x.value||0);s[c.weaponStat]=(s[c.weaponStat]||0)+Number(c.weaponValue||0);return {atk:(c.baseAtk+c.weaponAtk)*(1+(s.atkPct+c.atkPct)/100)+s.atkFlat+c.atkFlat,hp:c.baseHp*(1+(s.hpPct+c.hpPct)/100)+s.hpFlat,def:c.baseDef*(1+(s.defPct+c.defPct)/100)+s.defFlat,em:s.em+c.em,cr:s.cr+c.cr,cd:s.cd+c.cd,er:100+s.er+c.er,dmg:s.dmg+c.dmg+(s[c.element.toLowerCase()+'Dmg']||0)}}
export function effective(c,team,index){let s=stats(c),b={atkPct:0,atkFlat:0,em:0,cr:0,cd:0,dmg:0,stellar:0,base:0,elevation:0,shred:0,defShred:0,defIgnore:0};for(const x of team.buffs){if(!x.enabled||!(x.target==='all'||Number(x.target)===index))continue;if(x.element!=='all'&&x.element!==c.element)continue;let u=clamp(x.uptime,0,100)/100;b[x.stat]=(b[x.stat]||0)+Number(x.value)*u} s.atk+=(c.baseAtk+c.weaponAtk)*b.atkPct/100+b.atkFlat;for(const k of ['em','cr','cd','dmg'])s[k]+=b[k];s.cr=clamp(s.cr,0,100);s.em=Math.max(0,s.em);return {s,b}}
export function hit(c,t,i,a){let {s,b}=effective(c,t,i);const res=resistance(t.res-b.shred),def=(c.level+100)/((c.level+100)+(t.enemyLevel+100)*(1-clamp(b.defShred,0,100)/100)*(1-clamp(b.defIgnore,0,100)/100));let base=s[a.scaling]*a.mult/100,raw;const stellar=a.mode==='ssw'||a.mode==='ssc';if(stellar){const rm=a.mode==='ssc'?(t.stacks===0?1:1.4+.05*clamp(t.stacks,1,12)):1;raw=(rm*base*(1+(c.stellarBase+b.base)/100)*(1+6*s.em/(s.em+2000)+(c.stellar+b.stellar)/100)+a.flat)*res*(1+(c.elevation+b.elevation)/100)}else if(a.mode==='swirl'){raw=.6*t.levelMultiplier*(1+16*s.em/(s.em+2000)+a.reactionBonus/100)*res}else {let amp=a.mode==='melt'?2:a.mode==='reverseMelt'||a.mode==='vape'?1.5:a.mode==='forwardVape'?2:1; if(amp>1)amp*=1+2.78*s.em/(s.em+1400)+a.reactionBonus/100;raw=(base+a.flat)*(1+(s.dmg+a.bonus)/100)*def*res*amp}const crit=a.mode==='swirl'?raw:raw*(1+s.cd/100),avg=a.mode==='swirl'?raw:raw*(1+s.cr/100*s.cd/100);return {normal:raw,crit,avg,total:avg*a.hits,def:stellar||a.mode==='swirl'?1:def,res,s,b}}
export function calc(t){const members=t.chars.map((c,i)=>{let rows=c.actions.map(a=>hit(c,t,i,a));return {rows,total:rows.reduce((n,r)=>n+r.total,0)}});let total=members.reduce((n,m)=>n+m.total,0)+t.extraDamage;let dps=total/Math.max(1,t.rotation);return {members,total,dps,time:dps>0?t.hp/dps+t.downtime:null}}
